include "globals.mzn";

enum Color = {Red, Green, Ivory, Yellow, Blue};
enum Nationality = {Englishman, Spaniard, Ukrainian, Norwegian, Japanese};
enum Drink = {Coffee, Tea, Milk, OrangeJuice, Water};
enum Pet = {Dog, Snails, Fox, Horse, Zebra};
enum Cigarette = {OldGold, Kools, Chesterfields, LuckyStrike, Parliaments};

int: N = 5;

array[1..N] of var Color: houseColor;
array[1..N] of var Nationality: houseNationality;
array[1..N] of var Drink: houseDrink;
array[1..N] of var Pet: housePet;
array[1..N] of var Cigarette: houseCigarette;

% Constraints
constraint houseNationality[3] == Ukrainian /\ houseDrink[3] == Milk; % Clue 8
constraint houseNationality[1] == Norwegian; % Clue 9

% Clue 1: The Englishman lives in the red house.
constraint exists(i in 1..N)(houseNationality[i] == Englishman -> houseColor[i] == Red);

% Clue 2: The Spaniard owns the dog.
constraint exists(i in 1..N)(houseNationality[i] == Spaniard -> housePet[i] == Dog);

% Clue 3: Coffee is drunk in the green house.
constraint exists(i in 1..N)(houseColor[i] == Green -> houseDrink[i] == Coffee);

% Clue 4: The Ukrainian drinks tea.
constraint exists(i in 1..N)(houseNationality[i] == Ukrainian -> houseDrink[i] == Tea);

% Clue 5: The green house is immediately to the right of the ivory house.
constraint exists(i in 1..N-1)(houseColor[i] == Ivory /\ houseColor[i + 1] == Green);

% Clue 6: The Old Gold smoker owns snails.
constraint exists(i in 1..N)(houseCigarette[i] == OldGold -> housePet[i] == Snails);

% Clue 7: Kools are smoked in the yellow house.
constraint exists(i in 1..N)(houseCigarette[i] == Kools -> houseColor[i] == Yellow);

% Clue 10: The man who smokes Chesterfields lives in the house next to the man with the fox.
constraint exists(i in 1..N)(houseCigarette[i] == Chesterfields -> (housePet[i-1] == Fox \/ housePet[i+1] == Fox));

% Clue 11: Kools are smoked in the house next to the house where the horse is kept.
constraint exists(i in 1..N)(houseCigarette[i] == Kools -> (housePet[i-1] == Horse \/ housePet[i+1] == Horse));

% Clue 12: The Lucky Strike smoker drinks orange juice.
constraint exists(i in 1..N)(houseCigarette[i] == LuckyStrike -> houseDrink[i] == OrangeJuice);

% Clue 13: The Japanese smokes Parliaments.
constraint exists(i in 1..N)(houseNationality[i] == Japanese -> houseCigarette[i] == Parliaments);

% Clue 14: The Norwegian lives next to the blue house.
constraint exists(i in 1..N)(houseNationality[i] == Norwegian -> (houseColor[i-1] == Blue \/ houseColor[i+1] == Blue));

% All different constraints
constraint alldifferent(houseColor);
constraint alldifferent(houseNationality);
constraint alldifferent(houseDrink);
constraint alldifferent(housePet);
constraint alldifferent(houseCigarette);

include "globals.mzn";

enum COLOR = {Blue, Red, Green};
enum ANIMAL = {Dog, Cat, Zebra};

array[1..3] of var COLOR: houseColor;
array[1..3] of var ANIMAL: houseAnimal;

% Each house has a unique color and animal
constraint alldifferent(houseColor);
constraint alldifferent(houseAnimal);

% The Cat lives in the Red House
constraint houseAnimal[2] == Cat;

% The Red House is the middle house
constraint houseColor[2] == Red;

% The Blue House is directly to the left of the Red House
constraint houseColor[1] == Blue;

% The Dog lives in the Blue House
constraint houseAnimal[1] == Dog;

% Constraint for the Zebra
var ANIMAL: zebraAnimal = Zebra;

% Finding the Zebra's house
constraint exists(i in 1..3)(houseAnimal[i] == zebraAnimal);

solve satisfy;

include "globals.mzn";

enum MOVE = {paper, rock, scissors};

var MOVE: your_move;

constraint your_move = paper; % Since paper beats rock

solve satisfy;

include "globals.mzn";

enum SUSPECT = { Miss_Scarlett, Colonel_Mustard, Professor_Plum };
enum WEAPON = { Candlestick, Revolver, Rope };
enum ROOM = { Kitchen, Library, Conservatory };

var SUSPECT: culprit;
var WEAPON: murder_weapon;
var ROOM: murder_room;

constraint culprit != Colonel_Mustard;
constraint culprit != Miss_Scarlett;
constraint murder_weapon != Revolver;
constraint murder_weapon != Rope;
constraint murder_room != Kitchen;
constraint murder_room != Library;

solve satisfy;

include "globals.mzn";

enum LETTERS = {S, E, N, D, M, O, R, Y};

array[LETTERS] of var 0..9: digit;

constraint alldifferent(digit);

constraint digit[S] > 0;  % S cannot be 0
constraint digit[M] > 0;  % M cannot be 0

% The actual equations derived from the addition
constraint (1000 * digit[S] + 100 * digit[E] + 10 * digit[N] + digit[D]) + 
           (1000 * digit[M] + 100 * digit[O] + 10 * digit[R] + digit[E]) = 
           (10000 * digit[M] + 1000 * digit[O] + 100 * digit[N] + 10 * digit[E] + digit[Y]);

solve satisfy;

include "globals.mzn";

enum Direction = {North, East, South, West, Pedestrian};

array[Direction] of var 1..5: order;

% Constraints for the arrival order
constraint alldifferent(order); % All must occupy different positions

% The pedestrian goes before the East car
constraint order[Pedestrian] < order[East];

% The pedestrian and the East car arrive at the same moment
constraint order[East] = order[Pedestrian];

% The South car arrives before the pedestrian and East car
constraint order[South] < order[Pedestrian];

% The North car and the West car arrive at the same moment, after the pedestrian and East car
constraint (order[North] = order[West]) /\ (order[North] > order[East]);

% Right-of-way for the North and West cars
constraint order[North] < order[West];

solve satisfy;

include "globals.mzn";

enum Outcome = {Denied, Approved, CounterOffer};

var int: priyaCreditScore = 680;
var int: samCreditScore = 750;
var int: combinedMonthlyIncome = 9000;
var int: combinedMonthlyDebt = 3200;
var int: requestedLoanAmount; % This will be set to exceed policy limits
var float: dtiRatio = combinedMonthlyDebt / combinedMonthlyIncome;

var Outcome: loanOutcome;

% Constraint 1: Check the lower of the two credit scores
constraint
    (min(priyaCreditScore, samCreditScore) < 600 -> loanOutcome = Denied) /\

% Constraint 2: Check the DTI ratio
    (dtiRatio > 0.43 -> loanOutcome = Denied) /\

% Constraints for Approved or CounterOffer
    (loanOutcome != Denied ->
        (requestedLoanAmount <= combinedMonthlyIncome * 0.43 * 1.5 -> loanOutcome = Approved) /\
        (requestedLoanAmount > combinedMonthlyIncome * 0.43 * 1.5 -> loanOutcome = CounterOffer)
    );

% Assuming some value for the requestedLoanAmount
requestedLoanAmount = combinedMonthlyIncome * 0.43 * 1.5 + 1; % Exceeds limit

solve satisfy;

include "globals.mzn";

enum DRUG = {A, B, C};
array[DRUG] of var 9..16: drugTime;

% Define the meal times
int: meal1 = 8;
int: meal2 = 13;

% Constraints
constraint 
    drugTime[B] >= drugTime[A] + 4 /\
    forall(i in DRUG)(drugTime[i] \notin [meal1, meal2]) -> (drugTime[i] >= meal1 + 2 \/ drugTime[i] <= meal2 - 2);

% Ensure all drug times are different
constraint alldifferent(drugTime);

solve satisfy;

include "globals.mzn";

enum COLOR = {red, green, blue, yellow};
enum ANIMAL = {dog, cat, bird, fish};
enum OWNER = {alice, bob, charlie, dave};

array[OWNER] of var COLOR: color;
array[OWNER] of var ANIMAL: animal;

% All owners have different colors
constraint alldifferent(color);

% All owners have different animals
constraint alldifferent(animal);

% Alice has a red house
constraint color[alice] = red;

% Bob owns a fish
constraint animal[bob] = fish;

% The person with the green house owns a dog
constraint (exists(i in OWNER)(color[i] = green -> animal[i] = dog));

% Charlie does not own a cat
constraint animal[charlie] != cat;

% The owner of a blue house is either Dave or the owner of the bird
constraint (color[dave] = blue \/ (exists(i in OWNER)(animal[i] = bird -> color[i] = blue)));

solve satisfy;

include "globals.mzn";

enum HOUSES = {1, 2, 3};
enum NEIGHBORS = {Ana, Bo, Cy};

array[HOUSES] of var NEIGHBORS: house_neighbors;

% Constraint: Ana lives in house 1
constraint house_neighbors[1] = Ana;

% Constraint: Bo does not live in house 2
constraint house_neighbors[2] != Bo;

% Constraint: All neighbors must live in different houses
constraint alldifferent(house_neighbors);

% Define the loudest laugh (arbitrary assignment for the purpose of model)
var NEIGHBORS: loudest_laugh;

% To be modeled later, add to ensure that one neighbor has the loudest laugh
constraint loudest_laugh in NEIGHBORS;

include "globals.mzn";

enum ITEM = {rice, book_set, skillet, first_aid, toolbox};

array[ITEM] of int: weight = [4, 3, 5, 2, 6];
array[ITEM] of int: value = [5, 4, 8, 6, 7];

array[ITEM] of var 0..1: packed;  % 0 if not packed, 1 if packed

% First-aid kit must be included
constraint packed[first_aid] = 1;

% Total weight constraint
constraint sum(i in ITEM)(weight[i] * packed[i]) <= 10;

% Maximize total value
var int: total_value = sum(i in ITEM)(value[i] * packed[i]);
solve maximize total_value;

include "globals.mzn";

enum HOUSE { 1, 2, 3, 4, 5 };
enum COLOR { red, blue, green, yellow, white };

array[HOUSE] of var COLOR: houseColor;

% Constraints based on the clues
constraint houseColor[1] = red;  % The red house is house 1
constraint houseColor[4] = white; % The white house is house 4
constraint exists(i in HOUSE)(exists(j in HOUSE)(j > i /\ houseColor[i] = blue /\ houseColor[j] = green)); % The green house is to the right of the blue house

% All houses must have different colors
constraint alldifferent(houseColor);

solve satisfy;

include "globals.mzn";

enum COMPARTMENTS = {C1, C2, C3, C4};
enum ITEMS = {ICE_CREAM, BEANS, FLOUR, BANANAS};

array[COMPARTMENTS] of var ITEMS: items;

constraint
    % The ice cream must not be in any compartment above freezing
    items[C1] == ICE_CREAM \/ 
    items[C2] == ICE_CREAM \/ 
    items[C3] == ICE_CREAM \/ 
    items[C4] == ICE_CREAM;

% Each item must be in a different compartment
constraint alldifferent(items);

include "globals.mzn";

enum ANIMAL = {wolf, rabbit, goat, parrot, tortoise};
array[1..5] of var ANIMAL: animalPen;

% Clue 1: The tortoise is in pen 1.
constraint animalPen[1] = tortoise;

% Clue 2: The parrot is in pen 2.
constraint animalPen[2] = parrot;

% Clue 3: The goat is in pen 3.
constraint animalPen[3] = goat;

% Clue 4: The rabbit is in a lower-numbered pen than the wolf.
% This implies that the wolf is not in pen 1 or 2 or 3
% Hence, we can use this to restrict positions.
constraint (exists(i in 1..5) (
    animalPen[i] = rabbit -> (exists(j in (i+1)..5)(animalPen[j] = wolf))
));

% Clue 5: The wolf preys on the rabbit.
% This implies that the wolf cannot be in the same pen as the rabbit.
constraint all_different(animalPen);

solve satisfy;
